krpano.action:
set(sandbox_enable_intro, false);
set(sandbox_enable_autorotate, false);
if(sb_intro == 1 OR sb_intro == '1' OR sb_intro == true OR sb_intro == 'true',
	set(sandbox_enable_intro, true);
);
if(sb_auto == 1 OR sb_auto == '1' OR sb_auto == true OR sb_auto == 'true',
	set(sandbox_enable_autorotate, true);
);

set(layer[dir_card_1].bgborder, '0');
set(layer[dir_card_2].bgborder, '0');
if(xml.scene == 'scene_xmgxffyyzzby_0000', set(layer[dir_card_1].bgborder, '2 0xFFFFFF 0.95'); );
if(xml.scene == 'scene_bhfzbuyyzzby_0000', set(layer[dir_card_2].bgborder, '2 0xFFFFFF 0.95'); );

stopdelayedcall(sandbox_xiangmu_markers_show);
stopdelayedcall(intro_expand);
stopdelayedcall(intro_done);
set(sandbox_intro_running, false);
loadscene(scene_xmgxffyyzzby_0000, null, MERGE, OPENBLEND(0.5, 0.0, 0.75, 0.05, linear));

stopdelayedcall(sandbox_xiqu_markers_show);
stopdelayedcall(intro_expand);
stopdelayedcall(intro_done);
set(sandbox_intro_running, false);
stoptween(view.hlookat);
stoptween(view.vlookat);
stoptween(view.fov);
stoptween(view.distortion);
set(view.distortion, 0.0);
loadscene(scene_bhfzbuyyzzby_0000, null, MERGE, OPENBLEND(0.5, 0.0, 0.75, 0.05, linear));

set(sandbox_xiqu_markers_ready, false);
sandbox_labels_apply_all_pos();
sandbox_filter_hide_all_labels();
if(hotspot[spot_bhly_logo], set(hotspot[spot_bhly_logo].visible, false); set(hotspot[spot_bhly_logo].alpha, 0); );
stopdelayedcall(sandbox_xiqu_markers_show);
delayedcall(sandbox_xiqu_markers_show, 3.0,
	set(sandbox_xiqu_markers_ready, true);
	sandbox_filter_apply_current();
);

if(sandbox_enable_intro == true,
	play_intro();
);

set(sandbox_xiangmu_markers_ready, false);
sandbox_buildings_set_visible(false);
stopdelayedcall(sandbox_xiangmu_markers_show);
delayedcall(sandbox_xiangmu_markers_show, 0.5,
	set(sandbox_xiangmu_markers_ready, true);
	sandbox_buildings_set_visible(true);
);

stopdelayedcall(dir_hits_enable);
if(layer[dir_bar].state == 'opened',
	set(layer[dir_bar].state, 'closed');
	set(layer[dir_hit_1].enabled, false);
	set(layer[dir_hit_2].enabled, false);
	if(device.mobile,
		tween(layer[dir_bar].x, -176, 0.45, easeOutCubic);
	  ,
		tween(layer[dir_bar].x, -242, 0.45, easeOutCubic);
	);
	set(layer[dir_toggle_icon].url, 'skin/dir_chevron_right.png');
  ,
	set(layer[dir_bar].state, 'opened');
	tween(layer[dir_bar].x, 0, 0.45, easeOutCubic);
	set(layer[dir_toggle_icon].url, 'skin/dir_chevron_left.png');
	delayedcall(dir_hits_enable, 0.45,
		set(layer[dir_hit_1].enabled, true);
		set(layer[dir_hit_2].enabled, true);
	);
);

skin_hideskin(instant);
set(layer[skin_layer].visible, false);
set(layer[skin_layer].enabled, false);
set(layer[skin_btn_show].visible, false);
set(layer[skin_btn_show].enabled, false);
set(layer[skin_btn_prev_fs].visible, false);
set(layer[skin_btn_prev_fs].enabled, false);
set(layer[skin_btn_next_fs].visible, false);
set(layer[skin_btn_next_fs].enabled, false);
if(layer[webvr_enterbutton],
	set(layer[webvr_enterbutton].visible, false);
	set(layer[webvr_enterbutton].enabled, false);
);

hide_skin_controlbar();
if(sandbox_enable_intro != true,
	set(control.usercontrol, all);
	set(view.distortion, 0.0);
	set(view.architectural, 0.0);
	set(view.pannini, 0.0);
	if(sandbox_enable_autorotate == true, set(autorotate.enabled, true));
);

if(sandbox_enable_intro != true, exit(); );

set(autorotate.enabled, false);
set(control.usercontrol, off);
set(sandbox_intro_running, true);

set(intro_h, -4.8);
set(intro_v, 30.7);
set(intro_fov, 89);
set(intro_fovmax, 140);

stoptween(view.hlookat);
stoptween(view.vlookat);
stoptween(view.fov);
stoptween(view.distortion);

set(view.fovmax, 170);
set(view.limitview, off);
set(view.architectural, 0.0);
set(view.pannini, 0.0);
lookat(get(intro_h), 90, 150, 1.0, 0, 0);

stopdelayedcall(intro_expand);
stopdelayedcall(intro_done);
delayedcall(intro_expand, 0.5,
	tween(view.hlookat, get(intro_h), 3.0, easeOutQuad);
	tween(view.vlookat, get(intro_v), 3.0, easeOutQuad);
	tween(view.fov, get(intro_fov), 3.0, easeOutQuad);
	tween(view.distortion, 0.0, 3.0, easeOutQuad);
	delayedcall(intro_done, 3.0,
		set(view.fovmax, get(intro_fovmax));
		set(view.limitview, auto);
		set(control.usercontrol, all);
		set(sandbox_intro_running, false);
		if(sandbox_enable_autorotate == true, set(autorotate.enabled, true));
		hide_skin_controlbar();
	);
);
